-- Study Abroad country content, BATCH 28: Burundi, Cabo Verde, CAR, Chad, Comoros, DRC, Djibouti, Equatorial Guinea, Eritrea, Guinea-Bissau.
-- Researched from public sources in November 2026 (see backend/TODO_country_tables.md for what still needs checking).
-- Text blocks fill the columns on countries; subject / course rows are linked to subjects / specializations
-- (country_sections.subject_id / specialization_id) so the website links them to those pages.
-- Replaces the earlier '[Sample]' / '[Placeholder]' rows of these 5 countries. Safe to re-run.
-- Requires alembic revision e6a3c9d1f4b7 (alembic upgrade head).
BEGIN;
DELETE FROM country_sections WHERE country_id IN (SELECT id FROM countries WHERE slug IN ('burundi', 'cabo-verde', 'central-african-republic', 'chad', 'comoros', 'democratic-republic-of-the-congo', 'djibouti', 'equatorial-guinea', 'eritrea', 'guinea-bissau'));
UPDATE countries SET why_title = 'Why study in Burundi?', why_body = '<p>Burundi offers French-taught degrees at the University of Burundi and a few private universities at low cost; EAC students get free study visas.<ul><li>French-medium teaching</li><li>University of Burundi</li><li>EAC membership</li><li>Low living costs</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>The Commissariat Général des Migrations issues study visas. One guide cites a US$90 one-month entry visa with extensions at US$70 a month; students from EAC countries get a free study visa. Non-EAC applicants should get written confirmation of the correct long-stay visa.</p><ul><li>Admission letter from a recognised institution</li><li>Recognised school certificate</li><li>Budget in US dollars cash for fees and daily costs</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Commissariat Général des Migrations and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>The university''s platforms and diplomas are in French.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Sources disagree.</p><ul><li>One guide says the University of Burundi charges no tuition; aggregators give BIF 200,000-600,000 a year (about US$70-$210); neither is verified</li><li>Ask for written fees</li><li>Living costs: about US$200-$400 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'burundi';
UPDATE countries SET why_title = 'Why study in Cabo Verde?', why_body = '<p>Cabo Verde has Portuguese-taught public and private universities in an island nation with tourism, ocean and renewable energy sectors.<ul><li>Portuguese-medium teaching</li><li>Universidade de Cabo Verde and UTA</li><li>Stable democracy</li><li>Island and ocean studies</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Whether you need a visa before travelling depends on nationality; the visa guidance found dates from 2014. Residence permit financial requirements are set by ministerial order, so ask the embassy for the current amount.</p><ul><li>Admission letter from a recognised institution</li><li>Residence permit for longer stays</li><li>Confirm with the Cabo Verde embassy</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Cabo Verde embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>You apply directly to each university; Uni-CV ran a special 2026-27 bachelor''s phase on 14-16 October 2026 (now closed). Selection uses entrance examinations.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Fee coverage for foreigners is unclear.</p><ul><li>The Minister of Education said tuition is free at Uni-CV and UTA for 2026-27; confirm in writing whether this covers foreign students</li><li>Aggregator estimate: US$1,000-$2,499 a year (unofficial)</li><li>Living costs: about US$500-$900 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> Portuguese proof for Portuguese-taught programmes</li></ul>' WHERE slug = 'cabo-verde';
UPDATE countries SET why_title = 'Why study in the Central African Republic?', why_body = '<p>The Central African Republic has one main public university, the Université de Bangui, with French-taught programmes; security is very difficult.<ul><li>Université de Bangui with over 15,000 students</li><li>French-medium teaching</li><li>Very limited facilities</li></ul></p><p>The UK advises against all travel except to Bangui and against all but essential travel to Bangui itself (guide). This page is informational only and does not recommend travel.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>The embassy in Paris offers a long-stay visa covering 45 to 90 days at about €300 (guide). Another source says apply at the nearest embassy after acceptance.</p><ul><li>Admission letter from the university</li><li>Check whether the university issues letters for visa purposes</li><li>Few ATMs; most places do not accept international cards</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official CAR embassy and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>No official admission information was found; contact the university directly.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No tuition figures were found.</p><ul><li>Contact the university for fees</li><li>Living costs: not estimated because of conditions</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'central-african-republic';
UPDATE countries SET why_title = 'Why study in Chad?', why_body = '<p>Chad has the University of N''Djamena teaching in French and Arabic; security conditions require careful checking.<ul><li>French and Arabic teaching</li><li>University of N''Djamena with 20 partner universities in 12 countries</li><li>Students from about 15 nationalities</li></ul></p><p>Check your government''s travel advice before planning.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>Since 11 May 2026 every new visa application goes through the official e-Visa Tchad platform, which shows no separate student visa; ask the university and the e-Visa office which visa to request.</p><ul><li>Admission letter from the university</li><li>Proof of funds may be asked; no minimum is published</li><li>Check the UK FCDO advice (against all but essential travel to the whole country as of 18 October 2026)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official e-Visa Tchad and the University of N''Djamena site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Contact the university for admission requirements.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official international fees or Chadian government scholarships open to foreigners were found.</p><ul><li>Aggregators: XAF 25,000-100,000 a year (about US$40-$165) at public universities; unverified</li><li>Ask the university for fees in writing</li><li>Living costs: about US$200-$400 a month (aggregator)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French or Arabic proof depending on programme</li></ul>' WHERE slug = 'chad';
UPDATE countries SET why_title = 'Why study in the Comoros?', why_body = '<p>The Comoros has one public university, the Université des Comores, with French-taught programmes and very limited information for foreign students.<ul><li>French-medium teaching</li><li>Université des Comores</li><li>Small island nation</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No official student visa page was found. British citizens need a visa and can get one on arrival for €30; other nationalities are directed to the Comorian embassy in Paris.</p><ul><li>Admission letter from the university</li><li>Email the university before applying</li><li>Confirm your home country recognises the degree</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Comorian embassy and the university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>A 25,000 KMF pre-registration fee was reported.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No published fees for foreign students.</p><ul><li>Aggregators: KMF 50,000-200,000 a year (about US$110-$440); unverified</li><li>No scholarship open to foreigners found</li><li>Living costs: not published</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'comoros';
UPDATE countries SET why_title = 'Why study in the Democratic Republic of the Congo?', why_body = '<p>The DR Congo has large public universities in Kinshasa and Lubumbashi teaching in French, in a country with serious security issues in parts.<ul><li>French-medium teaching</li><li>University of Kinshasa (about 29,580 students; 1% international)</li><li>University of Lubumbashi</li><li>Mining and tropical medicine strengths</li></ul></p><p>Check your government''s travel advice before planning.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No visa or entry requirements were found in this research; contact the DRC embassy and check your government''s travel advice.</p><ul><li>Admission letter from a Congolese university</li><li>Check the DRC immigration authority and embassy</li><li>Check your government''s travel advice</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official DRC embassy and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>No official international admission information was found.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No international tuition schedule was found.</p><ul><li>uniRank lists international fees as not reported</li><li>Contact the universities for fees</li><li>Living costs: not estimated</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'democratic-republic-of-the-congo';
UPDATE countries SET why_title = 'Why study in Djibouti?', why_body = '<p>Djibouti has the University of Djibouti, with French-taught programmes, in a small strategic Horn of Africa country.<ul><li>French-medium teaching</li><li>University of Djibouti (about 5% international students)</li><li>Port, logistics and trade sector</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No official student visa procedure was found. A guide lists passport, admission confirmation, plane tickets and financial information.</p><ul><li>Confirmation of admission at the University of Djibouti</li><li>Plane tickets and financial information</li><li>Check the Djibouti embassy</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Djibouti embassy and the University of Djibouti site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Contact the university directly.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Estimates are unverified.</p><ul><li>A guide puts public university fees for international students at US$1,500-$3,000 a year; uniRank lists none</li><li>Scholarships are limited</li><li>Living costs: not published</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> French proof for French-taught programmes</li></ul>' WHERE slug = 'djibouti';
UPDATE countries SET why_title = 'Why study in Equatorial Guinea?', why_body = '<p>Equatorial Guinea has the National University (UNGE), with Spanish-taught programmes, in an oil-producing Central African country.<ul><li>Spanish-medium teaching</li><li>UNGE</li><li>Oil and gas sector</li><li>Erasmus+ and bilateral projects</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A student visa is needed depending on nationality. Sources list an admission letter from a recognised institution, passport copies, proof of financial means and possibly a health certificate; another source adds full course payment receipt.</p><ul><li>Admission letter and proof of funds</li><li>Foreign qualifications admitted through convalidación (recognition of studies)</li><li>Confirm with the embassy for your country</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Equatorial Guinea embassy and UNGE site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Check the official UNGE website for requirements.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>Figures conflict.</p><ul><li>One source: UNGE bachelor''s tuition XAF 1,500,000</li><li>Guide: public university fees XAF 100,000-300,000 a year (about US$165-$500)</li><li>Living costs: about US$600-$1,000 a month (estimate)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> Spanish (B2 or higher) for Spanish-taught programmes</li></ul>' WHERE slug = 'equatorial-guinea';
UPDATE countries SET why_title = 'Why study in Eritrea?', why_body = '<p>Eritrea has a college-based higher-education system, and public information for international students is very limited.<ul><li>Eritrea Institute of Technology and other colleges</li><li>Orotta School of Medicine and Dentistry</li><li>Very limited information for international students</li></ul></p><p>The US advisory is Level 2, Canada advises avoiding non-essential travel, and the UK advises against travel to parts of Eritrea. Check current advice.</p>', visa_title = 'Student visa and residence permit', visa_body = '<p>No official student-visa guidance was found. Foreign nationals need a travel permit for travel outside Asmara. A visa from the Washington embassy takes at least 15 business days and is typically valid for one month, extendable at Immigration in Asmara.</p><ul><li>Admission letter from a recognised institution</li><li>Letter from school stating purpose and duration (aggregator)</li><li>A permit is needed for travel beyond 25 km of Asmara</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Eritrean embassy and your government''s travel advice site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>No admission information was found.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No tuition figures were found.</p><ul><li>Contact the institutions for fees</li><li>Living costs: not estimated</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> English or Tigrinya proof depending on programme</li></ul>' WHERE slug = 'eritrea';
UPDATE countries SET why_title = 'Why study in Guinea-Bissau?', why_body = '<p>Guinea-Bissau has a small higher-education system, with the Universidade Amílcar Cabral as the main institution, teaching in Portuguese.<ul><li>Portuguese-medium teaching</li><li>Universidade Amílcar Cabral</li><li>Universidade Lusófona da Guiné-Bissau</li><li>Small, low-cost system</li></ul></p>', visa_title = 'Student visa and residence permit', visa_body = '<p>A student visa is required; apply at the nearest Guinea-Bissau embassy or consulate after acceptance (aggregator). No official source was found.</p><ul><li>Admission letter from the institution</li><li>Passport and proof of funds</li><li>Check the embassy</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official Guinea-Bissau embassy and your university site before you apply.</em></p>', application_title = 'Application requirements', application_body = '<p>Contact the universities directly.</p><ul><li>Academic transcripts and certificates, legalised</li><li>Language proof for the language of instruction</li><li>Entrance requirements per programme</li><li>Passport copy and photographs</li><li>Medical certificate and police clearance where required</li></ul>', cost_title = 'Cost of studying', cost_body = '<p>No official fee schedule was found.</p><ul><li>Aggregator: public universities XOF 50,000-200,000 a year (about US$80-$330)</li><li>Living costs: about US$200-$400 a month (aggregator)</li></ul><p><em>Figures last checked in November 2026 from public sources. Rules and fees change often: always confirm on the official university site before you apply.</em></p>', eligibility_title = 'Eligibility criteria', eligibility_body = '<p>Requirements depend on the university and level.</p><ul><li><strong>Bachelor''s:</strong> a secondary school certificate (baccalauréat or equivalent)</li><li><strong>Master''s:</strong> a relevant bachelor''s degree (licence)</li><li><strong>Language:</strong> Portuguese proof for Portuguese-taught programmes</li></ul>' WHERE slug = 'guinea-bissau';
COMMIT;
